"""Semantic version ordering."""


def _pre_key(pre):
    # SemVer: numeric identifiers compare numerically and sort before
    # alphanumeric ones; alphanumerics compare lexically.
    out = []
    for ident in pre.split("."):
        if ident.isdigit():
            out.append((0, int(ident), ""))
        else:
            out.append((1, 0, ident))
    return tuple(out)


def key(version):
    """Sort key: a pre-release (1.0.0-alpha) sorts before its release (1.0.0)."""
    core, sep, pre = version.partition("-")
    nums = tuple(int(x) for x in core.split("."))
    if sep:
        # (0, ...) < (1, ()) so any pre-release precedes the plain release.
        return nums + (0, _pre_key(pre))
    return nums + (1, ())
